import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
REBALANCE_EVERY = 10
MIN_W, MAX_W = 0.015, 0.16
_seen_date = None
_bars_since_rebalance = REBALANCE_EVERY


def rank(x):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in x.items() if np.isfinite(v))
    if len(good) > 1:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out


def project(raw):
    # Projection onto a full-investment simplex with conservative per-asset bounds.
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in UNIVERSE}
    for _ in range(30):
        free = [s for s in UNIVERSE if MIN_W < w[s] < MAX_W]
        fixed = {s: w[s] for s in UNIVERSE if s not in free}
        if not free:
            break
        remainder = 1.0 - sum(fixed.values())
        total = sum(w[s] for s in free) or 1.0
        nw = dict(fixed)
        nw.update({s: remainder * w[s] / total for s in free})
        w = nw
        if all(MIN_W - 1e-9 <= w[s] <= MAX_W + 1e-9 for s in UNIVERSE):
            break
        for s in UNIVERSE:
            w[s] = min(MAX_W, max(MIN_W, w[s]))
    z = sum(w.values()) or 1.0
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _seen_date, _bars_since_rebalance
    account = get_account_dict()
    market = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=90)
        if df is None or len(df) < 25:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df.close, dtype=float)
        h = np.asarray(df.high, dtype=float)
        l = np.asarray(df.low, dtype=float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        market[s] = (c, h, l, r, str(df.iloc[-1].date))
    if len(market) < 12:
        return
    date = max(v[4] for v in market.values())
    if date != _seen_date:
        _bars_since_rebalance += 1
        _seen_date = date
    if _bars_since_rebalance < REBALANCE_EVERY:
        return

    # Read the persisted ensemble; fallback is only for a missing/invalid file.
    fallback = {"miner_3_clv_1d": (0.3395, "clv"), "peer_median_leadlag_5d": (0.2612, "peer"),
                "short_term_reversal_5d": (0.2012, "reversal"), "miner_2_risk_adjusted_momentum_20d": (0.1981, "momentum")}
    try:
        data = json.loads((Path(__file__).parent / "factors" / "factor_ensemble.json").read_text())
        selected = data.get("selected_factors", [])[:10]
        factors = [(str(x["factor_id"]), float(x.get("weight", 0)), int(x.get("direction", 1))) for x in selected]
    except Exception:
        factors = [(k, v[0], 1) for k, v in fallback.items()]
    aliases = {k: v[1] for k, v in fallback.items()}
    weights = {aliases.get(fid, fid): w * direction for fid, w, direction in factors if aliases.get(fid, fid) in ("clv", "peer", "reversal", "momentum")}
    if not weights:
        weights = {v[1]: v[0] for v in fallback.values()}
    total = sum(abs(v) for v in weights.values()) or 1.0
    weights = {k: v / total for k, v in weights.items()}

    clv, reversal, momentum, five, invvol = {}, {}, {}, {}, {}
    for s, (c, h, l, r, _) in market.items():
        vol = max(float(np.std(r[-20:])), 0.008)
        clv[s] = float(np.mean((2*c - h - l)[-3:] / np.maximum((h-l)[-3:], 1e-12)))
        reversal[s] = -float(np.mean(r[-5:]))
        momentum[s] = float((c[-1] / max(c[-21], 1e-12) - 1) / (vol + 0.01))
        five[s] = c[-1] / max(c[-6], 1e-12) - 1
        invvol[s] = 1.0 / vol
    median = float(np.median(list(five.values())))
    peer = {s: v - median for s, v in five.items()}
    rawf = {"clv": clv, "peer": peer, "reversal": reversal, "momentum": momentum}
    ranked = {k: rank(v) for k, v in rawf.items()}
    score = {s: sum(weights.get(k, 0) * ranked[k].get(s, 0.5) for k in ranked) for s in UNIVERSE}

    # Medium-risk bullish posture; only a confirmed two-horizon SPX decline gets defensive.
    spx = market.get("SPX")
    if spx is not None and spx[0][-1] < spx[0][-21] and spx[0][-1] < spx[0][-6]:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] += 0.18
        for s in ("BTC", "ETH", "WTI"): score[s] = max(0.05, score[s] - 0.10)
    avg = np.mean(list(invvol.values())) or 1.0
    raw = {s: max(0.01, score[s]) * (0.78 + 0.22 * invvol.get(s, avg) / avg) for s in UNIVERSE}
    target = project(raw)
    vals = np.array([score[s] for s in UNIVERSE])
    scale = max(float(vals.std()), 1e-12)
    forecast = {s: float(0.01 * (score[s] - vals.mean()) / scale) for s in UNIVERSE}
    ids = [fid for fid, _, _ in factors]
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    _bars_since_rebalance = 0

