CADENCE = 10
MIN_W, MAX_W = 0.025, 0.12
_seen_date = None
_days_since = CADENCE


def ranks(x):
    out = {s: 0.5 for s in UNIVERSE}
    a = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    if len(a) > 1:
        for i, (s, _) in enumerate(a):
            out[s] = (i + 1.0) / len(a)
    return out


def cap_weights(raw):
    # Projection onto the full-investment box; no cash sleeve.
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in UNIVERSE}
    for _ in range(100):
        free = [s for s in UNIVERSE if MIN_W < w[s] < MAX_W]
        fixed = [s for s in UNIVERSE if s not in free]
        rem = 1.0 - sum(w[s] for s in fixed)
        z = sum(w[s] for s in free)
        if not free or z <= 0:
            break
        nw = dict(w)
        for s in free:
            nw[s] = rem * w[s] / z
        w = nw
        old = dict(w)
        for s in UNIVERSE:
            w[s] = min(MAX_W, max(MIN_W, w[s]))
        if max(abs(w[s] - old[s]) for s in UNIVERSE) < 1e-10:
            break
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _seen_date, _days_since
    account = get_account_dict()
    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=100)
        if df is None or len(df) < 35:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df.close, dtype=float)
        h = np.asarray(df.high, dtype=float)
        l = np.asarray(df.low, dtype=float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        data[s] = (c, h, l, r, str(df.iloc[-1].date))
    if len(data) < 12:
        return
    date = max(v[4] for v in data.values())
    if date != _seen_date:
        _seen_date, _days_since = date, _days_since + 1
    if _days_since < CADENCE:
        return

    aliases = {
        "peer_median_leadlag_5d": "peer",
        "miner_2_risk_adjusted_momentum_20d": "momentum",
        "miner_3_clv_1d": "clv",
        "short_term_reversal_5d": "reversal",
    }
    default = {"peer": .30, "momentum": .27, "clv": .28, "reversal": .15}
    try:
        items = json.loads((Path(__file__).parent / "factors" / "factor_ensemble.json").read_text()).get("selected_factors", [])[:10]
    except Exception:
        items = []
    fw = {k: 0.0 for k in default}
    factor_ids = []
    for item in items:
        k = aliases.get(str(item.get("factor_id", "")))
        if k:
            fw[k] += max(0.0, float(item.get("weight", 0.0))) * (1 if int(item.get("direction", 1)) >= 0 else -1)
            factor_ids.append(str(item["factor_id"]))
    if sum(abs(v) for v in fw.values()) == 0:
        fw, factor_ids = default, list(aliases)
    z = sum(abs(v) for v in fw.values()) or 1.0
    fw = {k: v / z for k, v in fw.items()}

    factors = {k: {} for k in default}
    invvol = {}
    for s, (c, h, l, r, _) in data.items():
        vol = max(float(np.std(r[-20:])), .008)
        invvol[s] = 1.0 / vol
        # Smoothed CLV reduces one-day noise while retaining the selected factor's intent.
        factors["clv"][s] = float(np.mean((2*c[-3:] - h[-3:] - l[-3:]) / np.maximum(h[-3:] - l[-3:], 1e-12)))
        factors["reversal"][s] = -float(np.mean(r[-5:]))
        factors["momentum"][s] = float((c[-1] / max(c[-21], 1e-12) - 1) / (vol + .01))
        factors["peer"][s] = float(c[-1] / max(c[-6], 1e-12) - 1)
    med = np.median(list(factors["peer"].values()))
    factors["peer"] = {s: v - med for s, v in factors["peer"].items()}
    rr = {k: ranks(v) for k, v in factors.items()}
    score = {s: sum(fw[k] * rr[k].get(s, .5) for k in fw) for s in UNIVERSE}

    # High-risk consolidation: keep full investment but use a defensive tilt only
    # when both the 20d and 5d SPX trends are negative.
    spx = data.get("SPX")
    if spx is not None and spx[0][-1] < spx[0][-21] and spx[0][-1] < spx[0][-6]:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += .22
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= .14
    avg_vol = np.mean([1.0 / v for v in invvol.values()])
    raw = {s: max(.08, score[s]) * (.65 + .35 * invvol.get(s, 1 / avg_vol) * avg_vol) for s in UNIVERSE}
    target = cap_weights(raw)
    a = np.array(list(score.values()))
    sd = max(float(a.std()), 1e-8)
    forecast = {s: float(.006 * (score[s] - a.mean()) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    _days_since = 0

